tool_input.content:
#!/usr/bin/env node
/**
 * 8443 UI 还原 E2E 入口
 * 门禁（结构 + 布局）：npm run test:e2e:ref8443:gate
 * 像素回归（跨站 strict，默认 REF8443_MAX_DIFF_RATIO=0）：npm run test:e2e:ref8443:pixel
 */
import { spawnSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const env = { ...process.env, PLAYWRIGHT_CHROMIUM_EXECUTABLE: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE ?? '' }

function run(args) {
  const r = spawnSync('npx', ['playwright', 'test', '--config', 'playwright.ref8443.config.ts', ...args], {
    cwd: root,
    env,
    stdio: 'inherit',
    shell: true,
  })
  return r.status ?? 1
}

const mode = process.argv[2] ?? 'gate'
if (mode === 'gate') process.exit(run(['-g', '结构还原|布局一致']))
if (mode === 'pixel') process.exit(run(['-g', '像素一致']))
if (mode === 'all') process.exit(run([]))
console.error('Usage: node artifacts/ref8443-parity.mjs [gate|pixel|all]')
process.exit(2)

